import {RED,prepare} from './engine.mjs';
export function mountBoard(n,onSelect){const $=id=>document.getElementById(id);const regions=['zeroBoard','numberBoard','streetBoard','columnBoard','dozenBoard','outsideBoard','basketBoard'];regions.forEach(id=>$(id).replaceChildren());let selection={type:'red',value:''};const buttons=[];const add=(root,type,value,label,cls='')=>{const b=document.createElement('button');b.type='button';b.className='table-bet '+cls;b.textContent=label;b.dataset.target=type+':'+value;const prepared=prepare({type,value},n);b.setAttribute('aria-label',`${type}: ${label}, pays ${prepared.payout} to 1`);b.onclick=()=>{selection={type,value};buttons.forEach(x=>x.classList.toggle('selected',x===b));onSelect(selection,label);};buttons.push(b);root.append(b);return b;};
for(const v of [0,...(n>37?[37]:[]),...(n>38?[38]:[])])add($('zeroBoard'),'straight',String(v),v===37?'00':v===38?'000':'0','zero');
const pos=(b,xd,yd,xm,ym)=>{for(const[k,v]of Object.entries({xd,yd,xm,ym}))b.style.setProperty('--'+k,v+'%');};
for(let i=1;i<=36;i++){const r=Math.floor((i-1)/3),c=(i-1)%3;let b=add($('numberBoard'),'straight',String(i),String(i),'number '+(RED.has(i)?'red':'black'));pos(b,(r+.5)/12*100,(2-c+.5)/3*100,(c+.5)/3*100,(r+.5)/12*100);
if(c<2){b=add($('numberBoard'),'split',`${i},${i+1}`,'•','marker split');b.setAttribute('aria-label',`Split ${i} and ${i+1}, pays 17 to 1`);b.onclick=e=>choose(e.currentTarget,'split',`${i},${i+1}`,`${i} / ${i+1}`);pos(b,(r+.5)/12*100,(2-c)/3*100,(c+1)/3*100,(r+.5)/12*100);}
if(r<11){b=add($('numberBoard'),'split',`${i},${i+3}`,'•','marker split');b.setAttribute('aria-label',`Split ${i} and ${i+3}, pays 17 to 1`);b.onclick=e=>choose(e.currentTarget,'split',`${i},${i+3}`,`${i} / ${i+3}`);pos(b,(r+1)/12*100,(2-c+.5)/3*100,(c+.5)/3*100,(r+1)/12*100);}
if(c<2&&r<11){b=add($('numberBoard'),'corner',`${i},${i+1},${i+3},${i+4}`,'◆','marker corner');b.setAttribute('aria-label',`Corner ${i}, ${i+1}, ${i+3}, ${i+4}, pays 8 to 1`);b.onclick=e=>choose(e.currentTarget,'corner',`${i},${i+1},${i+3},${i+4}`,`${i}, ${i+1}, ${i+3}, ${i+4}`);pos(b,(r+1)/12*100,(2-c)/3*100,(c+1)/3*100,(r+1)/12*100);}}
function choose(b,type,value,label){buttons.forEach(x=>x.classList.toggle('selected',x===b));onSelect({type,value},label);}
for(let i=1;i<=34;i+=3){const nums=[i,i+1,i+2];add($('streetBoard'),'street',nums.join(','),`${i}–${i+2}`,'street').title=`Street ${nums.join(', ')}, 11:1`;}
const six=document.createElement('div');six.className='six-lines';$('streetBoard').after(six);document.querySelectorAll('.six-lines').forEach(x=>{if(x!==six)x.remove();});for(let i=1;i<=31;i+=3)add(six,'six',Array.from({length:6},(_,j)=>i+j).join(','),`${i}–${i+5}`,'six');
for(let i=1;i<=3;i++){add($('columnBoard'),'column',String(i),`Column ${i} · 2:1`);add($('dozenBoard'),'dozen',String(i),`${(i-1)*12+1}–${i*12} · 2:1`);}for(const [type,label]of [['low','1–18'],['even','Even'],['red','Red'],['black','Black'],['odd','Odd'],['high','19–36']])add($('outsideBoard'),type,'',label,type==='red'?'red':'');if(n===38)add($('basketBoard'),'basket','','0 / 00 / 1 / 2 / 3 · 6:1','basket');
}
